<script setup lang="ts">
import { computed,ref } from 'vue'
import AppPage from '../../components/AppPage.vue'
import Icon from '../../components/Icon.vue'
import DateStrip from '../../components/DateStrip.vue'
import EmptyState from '../../components/EmptyState.vue'
import { useHealthStore } from '../../stores/health'
import { dateKey,dateLabel,weekDays } from '../../domain/dates'
import { navigate } from '../../utils/ui'
const store=useHealthStore(),date=ref(dateKey())
const days=computed(()=>weekDays(date.value)),records=computed(()=>store.data.training.filter(x=>x.date===date.value))
const week=computed(()=>store.data.training.filter(x=>days.value.includes(x.date))),minutes=computed(()=>week.value.reduce((s,x)=>s+x.minutes,0)),activeDays=computed(()=>new Set(week.value.map(x=>x.date)).size)
const marks=computed(()=>[...new Set(store.data.training.map(x=>x.date))])
const chart=computed(()=>days.value.map(day=>({date:day,minutes:week.value.filter(x=>x.date===day).reduce((s,x)=>s+x.minutes,0)})))
const max=computed(()=>Math.max(60,...chart.value.map(x=>x.minutes)))
</script>
<template><AppPage tab="training"><view class="row-between"><view><text class="eyebrow">MOVE FOR YOURSELF</text><text class="page-title">每一次动起来，都算数</text></view><Icon name="dumbbell" :size="27"/></view><text class="page-description">不比较、不赶进度，保持自己的节奏。</text><DateStrip v-model="date" :marks="marks"/><view class="training-hero"><view class="hero-content"><text class="hero-eyebrow">THIS WEEK, YOUR WAY</text><text class="hero-title">给身体一点力量，{{ '\n' }}也给自己一点时间。</text><text class="hero-detail">记录类型与时长，回看每一份积累。</text></view><view class="hero-art"><view class="hero-orbit"/><Icon name="dumbbell" tone="white" :size="63"/></view></view><view class="card week-training"><view class="row-between mb-16"><text class="section-title">这一周的积累</text><text class="section-caption">{{ days[0].slice(5).replace('-','.') }} — {{ days[6].slice(5).replace('-','.') }}</text></view><view class="stats-grid"><view><text class="stat-number number">{{ week.length }}<text class="stat-unit">次</text></text><text class="stat-label">训练记录</text></view><view><text class="stat-number number">{{ minutes }}<text class="stat-unit">min</text></text><text class="stat-label">累计时长</text></view><view><text class="stat-number number">{{ activeDays }}<text class="stat-unit">天</text></text><text class="stat-label">运动天数</text></view></view><view class="training-bars"><button role="button" v-for="(item,i) in chart" :key="item.date" class="training-bar-item" :disabled="item.date>dateKey()" :aria-label="item.date+' '+item.minutes+'分钟'" @click="date=item.date"><text class="bar-value">{{ item.minutes || '' }}</text><view class="bar-track"><view class="bar-fill" :class="{selected:item.date===date}" :style="{height: item.minutes/max*100+'%'}"/></view><text class="bar-label" :class="{selected:item.date===date}">{{ ['一','二','三','四','五','六','日'][i] }}</text></button></view></view><view class="section"><view class="section-heading"><text class="section-title">{{ dateLabel(date) }}的训练</text><button role="button" class="text-link" @click="navigate('training-entry','date='+date)"><Icon name="plus" :size="14"/>记录训练</button></view><view v-if="records.length" class="entry-list"><view v-for="entry in records" :key="entry.id" class="entry-row" @click="navigate('training-entry','id='+entry.id)"><view class="training-type-icon"><Icon :name="entry.type==='力量训练'?'dumbbell':entry.type==='瑜伽拉伸'?'leaf':'fire'" :size="24"/></view><view class="grow"><text class="entry-name">{{ entry.type }}</text><text class="entry-detail">{{ entry.minutes }} 分钟 · {{ entry.feeling }}</text><text v-if="entry.note" class="entry-detail training-note">{{ entry.note }}</text></view><Icon name="arrow" tone="muted" :size="13"/></view></view><view v-else class="card"><EmptyState title="今天，按自己的节奏来" detail="力量、跑步或拉伸，选择让你舒服的运动。休息也很重要。" icon="dumbbell"><button role="button" class="btn-primary btn-small mt-16" @click="navigate('training-entry','date='+date)"><Icon name="plus" tone="white" :size="15"/>记一次训练</button></EmptyState></view></view><text class="footer-note">认真运动，也认真休息。{{ '\n' }}不估算运动消耗，不用训练抵消饮食。</text></AppPage></template>
<style scoped>.training-hero{display:flex;position:relative;background:var(--forest);border-radius:20px;padding:22px 19px;color:white;overflow:hidden;min-height:158px}.hero-content{position:relative;z-index:1}.hero-eyebrow{font-size:8px;letter-spacing:1.6px;color:#b3c5a7;display:block;margin-bottom:13px}.hero-title{font-size:18px;font-weight:550;line-height:1.7;letter-spacing:.5px}.hero-detail{display:block;font-size:9px;color:#b3c5a7;margin-top:11px}.hero-art{position:absolute;right:15px;top:42px;transform:rotate(-20deg);opacity:.62}.hero-orbit{position:absolute;width:125px;height:125px;border:1px solid #ffffff30;border-radius:50%;top:-30px;left:-30px}.hero-orbit:after{content:'';position:absolute;inset:15px;border:1px solid #ffffff20;border-radius:50%}.week-training{margin-top:17px;padding:19px}.week-training .section-title{font-size:13px}.week-training .section-caption{font-size:9px;letter-spacing:0}.week-training .stats-grid{padding:3px 0}.training-bars{display:flex;justify-content:space-between;margin-top:20px;gap:16px;height:113px}.training-bar-item{display:flex;flex-direction:column;flex:1;gap:8px;justify-content:flex-end}.bar-track{height:66px;width:100%;display:flex;align-items:flex-end}.bar-fill{width:100%;background:#dbe5cc;border-radius:6px 6px 3px 3px}.bar-fill.selected{background:#4c7b44}.bar-label{font-size:10px;color:var(--muted)}.bar-label.selected{color:var(--green);font-weight:600}.bar-value{font-size:9px;color:#839175;height:12px}.training-type-icon{width:45px;height:45px;border-radius:15px;background:#e8eedf;display:flex;align-items:center;justify-content:center;flex-shrink:0}.training-note{max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:3px}</style>
